package com.yuegang.zhihui.order.application;import com.yuegang.zhihui.inventory.api.*;import com.yuegang.zhihui.order.api.*;import com.yuegang.zhihui.order.infrastructure.*;import com.yuegang.zhihui.wallet.api.*;import java.time.*;import java.util.*;import javax.sql.*;import org.springframework.jdbc.core.*;
public final class CommerceReconciliationService{private final JdbcTemplate jdbc;private final CommerceReconciliationClient client;public CommerceReconciliationService(DataSource d,CommerceReconciliationClient c){jdbc=new JdbcTemplate(d);client=c;}public CommerceReconciliationView run(){var orders=jdbc.query("SELECT m.id,m.request_id,m.status,m.total_amount,m.currency,COALESCE(SUM(i.quantity),0) quantity FROM order_main m LEFT JOIN order_item i ON i.order_id=m.id GROUP BY m.id,m.request_id,m.status,m.total_amount,m.currency ORDER BY m.created_at DESC LIMIT 200",(r,n)->new Row(r.getString(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getString(5),r.getLong(6)));var errors=new ArrayList<CommerceReconciliationView.Discrepancy>();for(var order:orders){try{WalletReferenceView wallet=client.wallet(order.id);InventoryReferenceView inventory=client.inventory(order.request);boolean expectsPayment=Set.of("PAID","PROCESSING","COMPLETED","REFUNDING","REFUNDED").contains(order.status);if(wallet.paymentSucceeded()!=expectsPayment)errors.add(d(order,"WALLET_PAYMENT",Boolean.toString(expectsPayment),Boolean.toString(wallet.paymentSucceeded())));boolean expectsRefund="REFUNDED".equals(order.status);if(wallet.refundSucceeded()!=expectsRefund)errors.add(d(order,"WALLET_REFUND",Boolean.toString(expectsRefund),Boolean.toString(wallet.refundSucceeded())));long actual=switch(order.status){case"PENDING_PAYMENT"->inventory.lockedQuantity();case"CANCELLED","CLOSED"->inventory.releasedQuantity();case"REFUNDED"->inventory.returnedQuantity();default->inventory.soldQuantity();};if(actual!=order.quantity)errors.add(d(order,"INVENTORY_QUANTITY",Long.toString(order.quantity),Long.toString(actual)));}catch(RuntimeException e){errors.add(d(order,"UPSTREAM_QUERY","AVAILABLE",e.getClass().getSimpleName()));}}long inconsistent=errors.stream().map(CommerceReconciliationView.Discrepancy::orderId).distinct().count();return new CommerceReconciliationView(orders.size(),orders.size()-inconsistent,List.copyOf(errors),OffsetDateTime.now(ZoneOffset.UTC));}private static CommerceReconciliationView.Discrepancy d(Row r,String dimension,String expected,String actual){return new CommerceReconciliationView.Discrepancy(r.id,r.status,dimension,expected,actual);}private record Row(String id,String request,String status,java.math.BigDecimal total,String currency,long quantity){}}
